<script setup lang="ts">
import { shallowRef,ref,computed,watch,onBeforeUnmount } from 'vue';
import { RouterLink } from 'vue-router';
import { ApiError } from '../../api/client';
import { getProjects,getMaterials,type Project,type Material } from '../../api/materials';
import { getLLMConfig,previewContext,generateAssistant,saveAssistant,type AssistantOperation,type ContextSelection,type ContextPreview,type AssistantPreview,type SaveAssistantResult,type AssistantInput } from '../../api/assistant';
import ContextSelector from './ContextSelector.vue';
import SourceCitations from './SourceCitations.vue';
const props=defineProps<{questionId:number;draft?:string;sourceVersionId?:number;answerId?:number;sourceSessionItemId?:number;sourcePracticeReviewId?:number;disabled?:boolean;initialOpen?:boolean}>();
const emit=defineEmits<{saved:[result:SaveAssistantResult];apply:[value:{content:string;previewId:string}];cancel:[]}>();
const opened=shallowRef(false),optionsLoaded=shallowRef(false),projects=ref<Project[]>([]),materials=ref<Material[]>([]),configured=shallowRef(false),model=shallowRef(''),operation=shallowRef<AssistantOperation>(props.sourceVersionId||props.draft?'polish':'reference_answer');
const selection=ref<ContextSelection>({project_ids:[],material_ids:[],exclude_material_ids:[]}),context=shallowRef<ContextPreview|null>(null),result=shallowRef<AssistantPreview|null>(null),edited=shallowRef(''),busy=shallowRef(false),stage=shallowRef(''),error=shallowRef(''),success=shallowRef(''),saved=shallowRef(false);
let revision=0,optionRevision=0;
const canGenerate=computed(()=>operation.value==='reference_answer'||!!props.sourceVersionId||!!props.draft?.trim());
function message(e:unknown){return e instanceof ApiError?e.message:'AI 请求失败，原始正文已保留，请重试。';}
function input():AssistantInput{return {question_id:props.questionId,operation:operation.value,context:selection.value,...(operation.value==='reference_answer'?{}:props.sourceVersionId?{source_saved_answer_version_id:props.sourceVersionId}:{draft:props.draft??''})};}
async function options(){const r=++optionRevision;busy.value=true;stage.value='正在加载资料选择…';error.value='';try{const [p,m,c]=await Promise.all([getProjects(),getMaterials(false,true),getLLMConfig()]);if(r===optionRevision){projects.value=p;materials.value=m;configured.value=c.configured;model.value=c.model;optionsLoaded.value=true;}}catch(e){if(r===optionRevision)error.value=message(e);}finally{if(r===optionRevision)busy.value=false;}}
function toggle(event:Event){opened.value=(event.target as HTMLDetailsElement).open;if(opened.value&&!optionsLoaded.value){if(props.draft?.trim()||props.sourceVersionId)operation.value='polish';void options();}}
async function preview(){const r=revision;busy.value=true;stage.value='正在准备本次发送内容…';error.value='';context.value=null;try{const c=await previewContext(input());if(r===revision)context.value=c;}catch(e){if(r===revision)error.value=message(e);}finally{if(r===revision)busy.value=false;}}
async function generate(){if(!context.value||busy.value)return;const r=revision;busy.value=true;stage.value='模型正在生成，请稍候…';error.value='';result.value=null;try{const data=await generateAssistant({...input(),context_token:context.value.context_token});if(r===revision){result.value=data;edited.value=data.content;saved.value=false;}}catch(e){if(r===revision){error.value=message(e);if(e instanceof ApiError&&['ASSISTANT_CONTEXT_STALE','CONTEXT_UNAVAILABLE'].includes(e.code))context.value=null;}}finally{if(r===revision)busy.value=false;}}
async function save(kind:'output'|'new_answer'|'answer_version'){if(!result.value||busy.value||saved.value)return;const r=revision;busy.value=true;stage.value='正在保存…';error.value='';try{const data=await saveAssistant(result.value.preview_id,{save_kind:kind,...(kind!=='output'?{content:edited.value}:{}),...(kind==='answer_version'?{saved_answer_id:props.answerId}:{}),...(kind!=='output'&&props.sourceSessionItemId&&props.sourcePracticeReviewId?{source_session_item_id:props.sourceSessionItemId,source_practice_review_id:props.sourcePracticeReviewId}:{})});if(r===revision){saved.value=true;success.value=kind==='output'?'AI 输出已保存；它独立于你的回答和掌握度记录。':'回答已保存，原始正文和历史版本继续保留。';emit('saved',data);}}catch(e){if(r===revision)error.value=message(e);}finally{if(r===revision)busy.value=false;}}
function discard(){result.value=null;context.value=null;edited.value='';success.value='';saved.value=false;}
watch([()=>props.questionId,()=>props.sourceVersionId,()=>props.draft],()=>{revision++;busy.value=false;discard();}, {flush:'sync'});
watch([operation,selection],()=>{revision++;busy.value=false;discard();},{deep:true,flush:'sync'});
onBeforeUnmount(()=>{revision++;optionRevision++;});
</script>
<template><details class="assistant-panel" :open="initialOpen" @toggle="toggle"><summary>AI 辅助 · 润色、参考答案与分析</summary><div v-if="opened" class="assistant-workspace"><div class="assistant-heading"><div><h3>以事实为依据，完善自己的表达</h3><p class="helper">仅在点击生成后调用模型。AI 不改变评分、掌握度、复习日期或练习队列。</p></div><RouterLink to="/settings">模型设置</RouterLink></div><p v-if="!configured&&optionsLoaded" class="canonical-banner">尚未配置模型，请先打开模型设置。资料管理与普通练习仍可使用。</p><label>辅助方式<select v-model="operation" aria-label="AI 辅助方式" :disabled="busy||disabled"><option value="polish">润色回答</option><option value="reference_answer">生成参考答案</option><option value="analyze">分析回答</option></select></label><p v-if="sourceVersionId" class="helper">针对已保存版本 #{{ sourceVersionId }}；原版本不会被覆盖。</p><p v-if="!canGenerate" class="helper">先输入回答或选择保存版本，才可润色和分析。</p><ContextSelector v-if="optionsLoaded" v-model="selection" :projects="projects" :materials="materials" :busy="busy||!!disabled"/><p v-if="error" role="alert">{{ error }}</p><p v-if="success" role="status" class="success-banner">{{ success }}</p><p v-if="busy" role="status">{{ stage }}</p><div class="action-row"><button type="button" :disabled="busy||disabled||!canGenerate||!optionsLoaded" @click="preview">预览本次发送内容</button><button v-if="error&&!optionsLoaded" type="button" :disabled="busy" @click="options">重新加载资料</button></div><section v-if="context" class="context-preview" aria-label="本次发送内容"><p class="helper">{{ context.notice }}</p><SourceCitations :sources="context.sources" show-chunks/><div class="action-row"><button type="button" class="primary" :disabled="busy||disabled||!configured" @click="generate">{{ busy?'正在生成…':'确认发送并生成' }}</button><span class="helper">模型：{{ model||'未配置' }}</span></div></section><section v-if="result" class="assistant-result" aria-label="AI 生成预览"><div class="action-row"><h4>{{ {polish:'润色结果',reference_answer:'参考答案',analyze:'分析建议'}[result.operation] }}</h4><span class="badge">临时预览 · 尚未自动保存</span></div><p class="assistant-output-text">{{ result.content }}</p><SourceCitations :sources="result.sources"/><template v-if="result.operation!=='analyze'"><details><summary>整理后保存为自己的回答</summary><label>准备保存的正文<textarea v-model="edited" aria-label="AI 结果编辑正文" :disabled="busy||saved||disabled" maxlength="100000"/></label><p class="helper">直接保存参考答案标为 AI 生成；修改后保存或润色版本标为 AI 辅助。新版本默认未评分。</p><div class="action-row"><button class="primary" :disabled="busy||saved||disabled||!edited.trim()" @click="save('new_answer')">保存为新回答</button><button v-if="answerId" :disabled="busy||saved||disabled||!edited.trim()" @click="save('answer_version')">保存为此回答的新版本</button><button v-if="draft!==undefined" :disabled="busy||saved||disabled" @click="emit('apply',{content:edited,previewId:result.preview_id})">应用到临时回答</button></div></details></template><div class="action-row result-actions"><button :disabled="busy||saved||disabled" @click="save('output')">{{ result.operation==='reference_answer'?'保存参考答案':result.operation==='analyze'?'保存分析建议':'保存润色结果' }}</button><button :disabled="busy" @click="discard">放弃预览</button><button v-if="initialOpen" :disabled="busy" @click="emit('cancel')">关闭辅助</button></div></section></div></details></template>
<style scoped>
.assistant-panel{margin:24px 0;border:1px solid var(--border);border-radius:12px;background:var(--surface);padding:8px 24px;}.assistant-panel>summary{color:var(--brand-hover);}.assistant-workspace{display:grid;gap:20px;padding:16px 0;}.assistant-heading{display:flex;justify-content:space-between;gap:20px;}.assistant-heading h3{margin-bottom:8px;}.assistant-heading p{margin:0;}.assistant-workspace>label{max-width:420px;}.context-preview,.assistant-result{border-top:1px solid var(--border);padding-top:20px;}.context-preview>.action-row{margin-top:16px;}.assistant-output-text{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9;font-size:15px;}.assistant-result h4{margin:0;}.assistant-result>.action-row{margin-bottom:16px;}.assistant-result textarea{min-height:220px;}.result-actions{margin-top:20px;}@media(max-width:767px){.assistant-panel{padding:8px 16px;}.assistant-heading{flex-direction:column;gap:8px;}.assistant-result .action-row{align-items:stretch;}}
</style>
